//! Test-only process fixture, built only with fault-injection enabled.
use infinite_store::*;use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
fn changes()->Vec<Change>{vec![Change{key:RecordKey{table:1,id:1},value:Some(b"after".as_slice().into())},Change{key:RecordKey{table:1,id:2},value:Some(b"new".as_slice().into())}]}
fn main(){let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),4);let stage=match args[3].as_str(){"BeforeCreate"=>IoStage::BeforeCreate,"AfterWrite"=>IoStage::AfterWrite,"AfterFileSync"=>IoStage::AfterFileSync,"BeforePublish"=>IoStage::BeforePublish,"AfterPublish"=>IoStage::AfterPublish,"BeforeDirectorySync"=>IoStage::BeforeDirectorySync,"BeforePrune"=>IoStage::BeforePrune,"AfterPrune"=>IoStage::AfterPrune,_=>panic!("unknown phase")};let mut journal=Journal::open(&args[1],JournalOptions::default()).unwrap();let checkpoint=args[2]=="checkpoint";if checkpoint{journal.commit(journal.mark(),&changes()).unwrap();}let seen=AtomicUsize::new(0);journal.set_fault_hook(Some(Arc::new(move|p|{if p.stage==stage{let at=seen.fetch_add(1,Ordering::Relaxed);if stage!=IoStage::AfterPrune||at==1{std::process::exit(73);}}Ok(())})));if checkpoint{journal.checkpoint().unwrap();}else{journal.commit(journal.mark(),&changes()).unwrap();}panic!("requested crash phase not reached");}
